function srvReady(){var s=srv();return !!(s&&s.url);}
function upName(){var s=srv();return s&&s.mode==='serwer'?'Na serwer':'Zapisz na Dysku';}
function btn(act,label,icon,pri){return '<button class="fa'+(pri?' pri':'')+'" data-act="'+act+'" type="button">'+(icon||'')+label+'</button>';}
function renderFiles(){
  $('#filesCount').textContent=FILES.length?String(FILES.length):'';
  $('#sheetLead').textContent=W_APCE?'W aplikacji Gemini nie da się pobrać ani udostępnić pliku, więc pliki trafiają na Twój Dysk Google — do folderu „Pracownia Fotoksiążki”. Stamtąd pobierzesz je, udostępnisz albo wyślesz do drukarni.':'Zapisz plik na Dysku Google, pobierz go na urządzenie albo udostępnij dalej.';
  var box=$('#fileList');if(!box)return;
  if(!FILES.length){box.innerHTML='<p class="nofiles">Tu pojawi się każdy plik, który zapiszesz w Ramkach, Okładce albo Odbitkach.</p>';$('#shareAll').classList.remove('on');return;}
  var b=batch(),shareOk=canShare([FILES[0]]),ready=srvReady();
  var all=$('#shareAll');all.classList.toggle('on',b.length>1&&canShare(b));all.innerHTML=IC.share+' Udostępnij wszystkie nowe ('+b.length+')';
  box.innerHTML=FILES.map(function(f,i){
    var img=/^image\//.test(f.type),ext=(f.name.split('.').pop()||'').toUpperCase().slice(0,4),acts=[];
    if(ready)acts.push(btn('up',f.upState==='ok'?'Zapisz ponownie':upName(),IC.up,f.upState!=='ok'));
    if(shareOk)acts.push(btn('share','Udostępnij',IC.share,!ready));
    if(!W_APCE){acts.push(btn('dl','Pobierz',IC.dl,false));acts.push(btn('open','Otwórz',IC.open,false));}
    if(!ready)acts.push(btn('setup',W_APCE?'Ustaw zapis na Dysk Google':'Dysk Google…',IC.up,W_APCE));
    var run=f.upState==='run'||f.upState==='wait';
    return '<div class="frow'+(i===0?' new':'')+'" data-id="'+f.id+'">'+
      '<div class="fmeta"><div class="fthumb"'+(img?' style="background-image:url('+f.url+')"':'')+'>'+(img?'':esc(ext))+'</div>'+
      '<div class="fname"><b title="'+esc(f.name)+'">'+esc(f.name)+'</b><small>'+fmtSize(f.size)+', z aplikacji '+esc(nameOf(f.app))+'</small></div></div>'+
      '<div class="facts n'+Math.min(acts.length,4)+'">'+acts.join('')+'</div>'+
      '<div class="upbar'+(run?' on':'')+'"><i style="width:'+(f.upPct||0)+'%"></i></div>'+
      '<p class="fnote '+f.noteCls+'" role="status">'+esc(f.note)+'</p>'+
      (f.link&&f.drive?'<div class="linkbox"><a class="fa" href="'+esc(f.link)+'" target="_blank" rel="noopener">'+IC.open+'Otwórz na Dysku</a></div>':'')+
      (f.link&&!f.drive?'<div class="linkbox"><input readonly value="'+esc(f.link)+'" aria-label="Link do pliku"><button class="fa" data-act="copy" type="button">Kopiuj link</button><button class="fa" data-act="mail" type="button">Wyślij e-mailem</button></div>':'')+
      '</div>';
  }).join('');
}
function note(f,msg,cls){f.note=msg;f.noteCls=cls||'';var row=document.querySelector('.frow[data-id="'+f.id+'"] .fnote');if(row){row.textContent=msg;row.className='fnote '+(cls||'');}}
function setUp(f,pct,msg){
  f.upPct=pct;var st=S._upload;st.bar=pct;st.barAt=now();render();
  var row=document.querySelector('.frow[data-id="'+f.id+'"]');
  if(row){var bar=row.querySelector('.upbar');bar.classList.add('on');bar.querySelector('i').style.width=pct+'%';}
  if(msg)note(f,msg,'');
}
function openSheet(){renderFiles();$('#sheet').classList.add('show');}
function closeSheet(){$('#sheet').classList.remove('show');}
function goSetup(msg){closeSheet();go(null);var box=$('#srvBox');box.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(function(){(srv()&&srv().mode==='serwer'?$('#srvUrl'):$('#dyskUrl')).focus();},400);if(msg)toast(msg);}
function doShare(list,f){
  navigator.share({files:list.map(fileObj),title:list.length===1?list[0].name:'Pliki z Pracowni Fotoksiążki'}).then(function(){
    if(f)note(f,'Udostępniono.','ok');snd('done');
  },function(e){
    if(e&&e.name==='AbortError')return;
    var m=e&&e.name==='NotAllowedError'?'To okno Gemini zablokowało udostępnianie. Zapisz plik na Dysku Google i udostępnij go z aplikacji Dysk.':'Nie udało się udostępnić: '+((e&&e.message)||e);
    if(f)note(f,m,'err');else toast(m);snd('warn');
  });
}
function doDownload(f){
  var a=document.createElement('a');a.href=f.url;a.download=f.name;a.rel='noopener';a.style.display='none';
  document.body.appendChild(a);a.click();setTimeout(function(){a.remove();},1000);
  note(f,'Pobieranie uruchomione. Jeśli plik nie pojawił się w Pobranych, zapisz go na Dysku Google.','');
}
function doOpen(f){
  var w=null;try{w=window.open(f.url,'_blank');}catch(e){}
  if(!w)note(f,'To okno nie pozwala otwierać nowych kart. Zapisz plik na Dysku Google.','err');
}
function findLink(x,depth){
  if(depth>4||x==null)return '';
  if(typeof x==='string'){var m=/https?:\/\/[^\s"'<>]+/.exec(x);return m?m[0]:'';}
  if(typeof x==='object'){var keys=['url','link','href','location','download_url','downloadUrl','webViewLink','data','file','result'];
    for(var i=0;i<keys.length;i++){if(x[keys[i]]!=null){var r=findLink(x[keys[i]],depth+1);if(r)return r;}}
    for(var k in x){var r2=findLink(x[k],depth+1);if(r2)return r2;}}
  return '';
}
/* kolejka wysyłek: pliki idą po kolei, żeby nie zapchać łącza */
var upQ=[],upRun=false;
function queueUp(f){if(f.upState==='run'||f.upState==='wait')return;f.upState='wait';f.upPct=0;note(f,'Czeka na wysłanie…','');renderFiles();upQ.push(f);nextUp();}
function nextUp(){
  if(upRun||!upQ.length)return;upRun=true;var f=upQ.shift(),s=srv();f.upState='run';
  var st=S._upload;st.inflight=1;st.bar=0;st.barAt=now();snd('start');render();
  (s&&s.mode==='serwer'?upServer:upDrive)(f,s,function(){st.inflight=0;st.bar=null;render();upRun=false;nextUp();});
}
function doUpload(f){if(!srvReady()){goSetup('Najpierw ustaw zapis na Dysk Google.');return;}queueUp(f);}
/* --- Dysk Google przez Twój skrypt Google (bez klucza API, na Twoim koncie) --- */
var CH=5*1024*1024;   /* części po 5 MB — skrypt Google przyjmuje je bez problemu */
function readB64(blob){return new Promise(function(res,rej){var r=new FileReader();r.onload=function(){var s=String(r.result);res(s.slice(s.indexOf(',')+1));};r.onerror=function(){rej(r.error||new Error('odczyt pliku'));};r.readAsDataURL(blob);});}
function gasPost(url,obj){
  /* Bez nasłuchu postępu wysyłania i bez własnych nagłówków — inaczej przeglądarka wysłałaby
     zapytanie wstępne (CORS), którego skrypty Google nie obsługują. */
  return new Promise(function(res,rej){
    var x=new XMLHttpRequest();x.open('POST',url,true);x.setRequestHeader('Content-Type','text/plain;charset=utf-8');
    x.onload=function(){var j=null;try{j=JSON.parse(x.responseText);}catch(e){}
      if(x.status>=200&&x.status<300&&j)res(j);else rej(new Error(x.status?'odpowiedź '+x.status+(j&&j.error?' ('+j.error+')':''):'brak połączenia'));};
    x.onerror=function(){rej(new Error('brak połączenia ze skryptem'));};
    x.send(JSON.stringify(obj));
  });
}
function upDrive(f,s,done){
  var total=f.size,od=0,sesja='',proby=0;
  setUp(f,0,'Łączę się z Dyskiem Google…');
  function pct(){return total?od/total*100:100;}
  function czesc(){
    var kawalek=f.blob.slice(od,Math.min(total,od+CH));
    var t0=now(),tik=setInterval(function(){setUp(f,Math.min(pct()+kawalek.size/total*100*0.9,pct()+kawalek.size/total*100*(1-Math.exp(-(now()-t0)/8000))),null);},500);
    return readB64(kawalek).then(function(b64){return gasPost(s.url,{akcja:'czesc',kod:s.kod||'',sesja:sesja,od:od,rozmiar:total,dane:b64});})
      .then(function(r){clearInterval(tik);if(!r.ok)throw new Error(r.error||'Dysk odrzucił część pliku');
        od+=kawalek.size;proby=0;setUp(f,pct(),'Zapisuję na Dysku: '+Math.floor(pct())+'%');
        return r.gotowe?r:czesc();},
      function(err){clearInterval(tik);return ponow(err);});
  }
  function ponow(err){
    if(++proby>3)throw err;
    note(f,'Chwilowy problem z połączeniem — ponawiam ('+proby+' z 3)…','');
    return new Promise(function(ok){setTimeout(ok,1500*proby);})
      .then(function(){return gasPost(s.url,{akcja:'stan',kod:s.kod||'',sesja:sesja,rozmiar:total});})
      .then(function(r){if(!r.ok)throw new Error(r.error||'błąd');if(r.gotowe)return r;od=r.odebrano||0;return czesc();},ponow);
  }
  gasPost(s.url,{akcja:'start',kod:s.kod||'',nazwa:f.name,typ:f.type,rozmiar:total})
    .then(function(j){if(!j.ok)throw new Error(j.error||'Dysk odmówił');sesja=j.sesja;return czesc();})
    .then(function(r){
      f.upState='ok';f.upPct=100;f.drive=true;f.link=r.link||'';
      f.note='Zapisano na Dysku Google w folderze „'+(r.folder||'Pracownia Fotoksiążki')+'”.';f.noteCls='ok';
      snd('done');toast(f.name+': zapisano na Dysku.');renderFiles();done();
    },function(err){
      f.upState='err';f.noteCls='err';
      f.note='Nie udało się zapisać na Dysku: '+((err&&err.message)||err)+'. Sprawdź adres skryptu i kod dostępu w menu (Zapis plików na Dysk Google).';
      snd('error');renderFiles();done();
    });
}
/* --- własny serwer (POST multipart) --- */
function upServer(f,s,done){
  var xhr=new XMLHttpRequest(),fd=new FormData();
  fd.append(s.field||'file',f.blob,f.name);
  xhr.open('POST',s.url,true);
  if(s.auth)try{xhr.setRequestHeader('Authorization',s.auth);}catch(e){}
  setUp(f,0,'Wysyłam na serwer…');
  xhr.upload.onprogress=function(e){if(e.lengthComputable){var p=e.loaded/e.total*100;setUp(f,p,'Wysyłam na serwer: '+Math.floor(p)+'%');}};
  xhr.onload=function(){
    if(xhr.status>=200&&xhr.status<300){
      var link='';try{link=findLink(JSON.parse(xhr.responseText),0);}catch(e){link=findLink(xhr.responseText||'',0);}
      if(!link)link=xhr.getResponseHeader('Location')||'';
      f.upState='ok';f.upPct=100;f.drive=false;f.link=link;f.note=link?'Wysłano. Link do pliku:':'Wysłano na serwer (serwer nie zwrócił linku).';f.noteCls='ok';
      snd('done');
    }else{f.upState='err';f.note='Serwer odrzucił plik (kod '+xhr.status+'). Sprawdź adres i token w ustawieniach.';f.noteCls='err';snd('error');}
    renderFiles();done();
  };
  xhr.onerror=function(){f.upState='err';f.noteCls='err';
    f.note='Nie udało się połączyć z serwerem. Możliwe przyczyny: zły adres, serwer nie zezwala na wysyłanie z przeglądarki (CORS) albo Gemini blokuje połączenia z tego okna.';
    snd('error');renderFiles();done();};
  xhr.send(fd);
}
$('#fileList').addEventListener('click',function(e){
  var btn=e.target.closest('[data-act]');if(!btn)return;
  var id=+btn.closest('.frow').getAttribute('data-id'),f=null;
  for(var i=0;i<FILES.length;i++)if(FILES[i].id===id)f=FILES[i];if(!f)return;
  var act=btn.getAttribute('data-act');
  if(act==='share')doShare([f],f);
  else if(act==='dl')doDownload(f);
  else if(act==='open')doOpen(f);
  else if(act==='up')doUpload(f);
  else if(act==='setup')goSetup('Ustaw zapis na Dysk Google — wystarczy raz.');
  else if(act==='copy'){var inp=btn.parentNode.querySelector('input');
    (navigator.clipboard&&navigator.clipboard.writeText?navigator.clipboard.writeText(f.link):Promise.reject()).then(function(){note(f,'Link skopiowany.','ok');},function(){inp.select();try{document.execCommand('copy');note(f,'Link skopiowany.','ok');}catch(x){note(f,'Zaznaczyłem link — skopiuj go ręcznie.','');}});}
  else if(act==='mail'){location.href='mailto:?subject='+encodeURIComponent(f.name)+'&body='+encodeURIComponent('Plik z Pracowni Fotoksiążki: '+f.name+'\n'+f.link);}
});
