/* --- ustawienia zapisu --- */
(function(){
  var s=srv()||{},mode=s.mode||'dysk',auto=s.auto!==false;
  $('#dyskUrl').value=s.mode==='dysk'?s.url||'':'';$('#dyskKod').value=s.kod||'';
  $('#srvUrl').value=s.mode==='serwer'?s.url||'':'';$('#srvField').value=s.field||'';$('#srvAuth').value=s.auth||'';
  function pokaz(){
    document.querySelectorAll('.seg [data-mode]').forEach(function(b){b.setAttribute('aria-checked',String(b.getAttribute('data-mode')===mode));});
    $('#modeDysk').hidden=mode!=='dysk';$('#modeSerwer').hidden=mode!=='serwer';
    $('#autoOpt').setAttribute('aria-pressed',String(auto));$('#srvTest').hidden=mode!=='dysk';
  }
  function stan(msg,cls){var el=$('#srvState');el.textContent=msg;el.className='srv-state '+(cls||'');}
  function opis(){var v=srv();if(!v||!v.url)return stan('Nie ustawiono — pliki zostają tylko w tym oknie.');
    stan(v.mode==='dysk'?'Ustawione: zapis na Dysk Google'+(v.auto!==false?', automatycznie po każdym zapisie.':'.'):'Ustawione: własny serwer '+v.url.replace(/^https?:\/\//,'').split('/')[0]+'.','ok');}
  function zbierz(){
    if(mode==='dysk')return {mode:'dysk',url:$('#dyskUrl').value.trim(),kod:$('#dyskKod').value.trim(),auto:auto};
    return {mode:'serwer',url:$('#srvUrl').value.trim(),field:$('#srvField').value.trim()||'file',auth:$('#srvAuth').value.trim(),auto:auto};
  }
  document.querySelectorAll('.seg [data-mode]').forEach(function(b){b.addEventListener('click',function(){mode=b.getAttribute('data-mode');pokaz();});});
  $('#autoOpt').addEventListener('click',function(){auto=!auto;pokaz();});
  $('#srvSave').addEventListener('click',function(){
    var v=zbierz();
    if(!v.url){stan('Wpisz adres.','err');return;}
    if(!/^https?:\/\//i.test(v.url)){stan('Adres musi zaczynać się od https://','err');return;}
    if(v.mode==='dysk'&&!/\/exec(\?|$)/.test(v.url)&&/script\.google\.com/.test(v.url)){stan('To nie jest adres aplikacji internetowej — powinien kończyć się na /exec.','err');return;}
    try{localStorage.setItem('pracownia.serwer',JSON.stringify(v));}catch(e){}
    opis();renderFiles();snd('step',5);
  });
  $('#srvTest').addEventListener('click',function(){
    var v=zbierz();if(!v.url){stan('Wpisz adres skryptu.','err');return;}
    stan('Sprawdzam połączenie z Dyskiem…');
    gasPost(v.url,{akcja:'test',kod:v.kod}).then(function(r){
      if(r.ok){stan('Połączono. Pliki trafią do folderu „'+(r.folder||'Pracownia Fotoksiążki')+'” na Twoim Dysku Google.','ok');snd('done');}
      else{stan('Skrypt odpowiedział, ale: '+(r.error||'błąd')+'.','err');snd('error');}
    },function(e){stan('Brak połączenia ze skryptem ('+e.message+'). Sprawdź adres i czy wdrożenie ma dostęp „Każdy”.','err');snd('error');});
  });
  $('#srvClear').addEventListener('click',function(){try{localStorage.removeItem('pracownia.serwer');}catch(e){}
    $('#dyskUrl').value=$('#dyskKod').value=$('#srvUrl').value=$('#srvField').value=$('#srvAuth').value='';opis();renderFiles();});
  pokaz();opis();
})();

