function decode(id){return window.__PRACOWNIA_SRC[id];}
function buildDoc(id){
  var html=decode(id);
  var head='<script>('+bridge.toString()+')();<\/script>';
  if(CANVAS.on){
    var body=CANVAS.cfg?JSON.stringify(CANVAS.cfg).replace(/</g,'\\u003c'):'';
    head='<script type="text/plain" data-bard-client-injected>'+body+'<\/script>'+head;
  }
  html=html.replace(/<head(\s[^>]*)?>/i,function(m){return m+head;});
  if(THEME[id]) html=html.replace(/<\/head>/i,function(m){return '<style id="pracownia-motyw">'+THEME[id]+'</style>'+m;});
  return html;
}
function ensureFrame(id){
  if(frames[id])return frames[id];
  var f=document.createElement('iframe');f.setAttribute('data-app',id);f.title=nameOf(id);
  f.setAttribute('allow','screen-wake-lock; clipboard-write; fullscreen; web-share');
  f.srcdoc=buildDoc(id);$('#stage').appendChild(f);frames[id]=f;return f;
}
function go(id,fromHash){
  gesture();
  if(id&&!S[id])id=null;
  current=id||null;
  document.body.classList.toggle('in-menu',!current);
  $('#menu').style.visibility=current?'hidden':'visible';
  $('#stage').classList.toggle('on',!!current);
  APPS.forEach(function(a){
    var btn=$('#sw-'+a.id);btn.setAttribute('aria-current',a.id===current?'page':'false');
    if(frames[a.id])frames[a.id].classList.toggle('on',a.id===current);
  });
  if(current){ensureFrame(current).classList.add('on');}
  if(!fromHash){try{history.replaceState(null,'',current?'#'+current:location.pathname+location.search);}catch(e){}}
  render();
}
